import React from 'react'

// `Event` is generated by Payload from src/collections/Events.ts
// (run `npm run generate:types` after changing fields).
import type { Event as EventType } from '@/payload-types'
import type { Locale } from '@/i18n'

type Props = {
  event: EventType
  locale?: Locale
}

// A plain presentational component: it receives data and renders it.
// It knows nothing about Payload or the database — the page fetches the data.
export function Event({ event, locale = 'de' }: Props) {
  const date = new Date(event.date).toLocaleString(locale === 'de' ? 'de-AT' : 'en-GB', {
    dateStyle: 'long',
    timeStyle: 'short',
  })

  return (
    <article className="event">
      <h2>{event.title}</h2>
      <p>
        <time dateTime={event.date}>{date}</time>
        {event.location && <> · {event.location}</>}
      </p>
      {event.description && <p>{event.description}</p>}
    </article>
  )
}
